import{_ as s,l as o,o as e,c as l,v as t,p as n,x as r,d as g,i as d,S as u}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"测试图形与 gauge","description":"","frontmatter":{"title":"测试图形与 gauge","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/test-patterns-gauges.md","filePath":"litho/test-patterns-gauges.md","lastUpdated":1789023840000}'),h={name:"litho/test-patterns-gauges.md"};function p(E,a,c,_,m,A){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="测试图形与-gauge" tabindex="-1">测试图形与 gauge <a class="header-anchor" href="#测试图形与-gauge" aria-label="Permalink to &quot;测试图形与 gauge&quot;">​</a></h1><div class="epigraph"><p>模型只在被量过的几何上受约束；gauge 的抽样偏差会变成全芯片的系统性盲目。</p><footer>—— 对照 OPC 校准 gauge、通过节距与二维测试键的产线通称</footer></div><p><a href="/litho/resist-model-calibration">上一课</a>把拟合协议钉死。缺口是样本从哪来：只放 1D 通过节距，二维线端与 SRAM 会成为外推。本课钉测试图形与 gauge。残差怎么读，留给[下一课](/litho/model-residual-analysis）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>校准集是实验设计。典型缺失：只有水平和垂直、没有 45°；只有线没有孔；只有标称剂量没有窗口角；只有逻辑密度没有 SRAM densest pitch；助条宽度未扫。SEM 收缩、量测部位（顶/底）、抽样数决定噪声地板——比噪声更密的模型项是假精度。</p><p>缺口是<strong>可观测性</strong>，不是再列 CM 参数名。把产品热区当唯一 gauge，会在 TAPOUT 前才发现模型从未见过那种邻域。</p><h3 id="gauge-必须进同一条计量链" tabindex="-1">Gauge 必须进同一条计量链 <a class="header-anchor" href="#gauge-必须进同一条计量链" aria-label="Permalink to &quot;Gauge 必须进同一条计量链&quot;">​</a></h3><p>CD-SEM 配方、收缩补偿、OCD 模型，要与将来监控一致。换 SEM 配方等于换数据集。计量课的 <a href="/litho/cd-sem-shrink">CD-SEM shrink</a> 在这里是校准偏差源。</p><p><span class="marginnote">故意放「禁戒节距」和「设计不允许但 OPC 可能长出的助条」进 gauge，才能约束病态区。只放 DRC 合法图形，模型在 MRC 边界上自由游荡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：通过节距、iso-dense、线端缩短、二维拐角、孔阵列、助条存在/缺失、FEM。统计：每类足够重复以估 SEM 噪声。权重：按产品重要性，而不是按好测。EUV 加随机：同一 gauge 多点平均，避免把泊松噪声拟合进确定性核。</p><p>与 DTCO：库里真实 clips 应占保持集，不只占宣传图。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成像算子对某些几何方向不敏感（信息论上不可观），对应参数会与别的项交换。gauge 的作用是打开这些方向的激励。若所有 gauge 都是长线，阈值与光学半径会混叠——残差课会看到「什么都能吃一点、什么都吃不干净」。</p>',14)),(e(),n(u,null,{default:r(()=>[d(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROD%5B%22%E4%BA%A7%E5%93%81%E5%85%B3%E9%94%AE%E5%87%A0%E4%BD%95%22%5D%20--%3E%20G%5B%22gauge%20%E7%9F%A9%E9%98%B5%22%5D%0A%20%20PHYS%5B%22%E9%80%9A%E8%BF%87%E8%8A%82%E8%B7%9D%20%2F%20FEM%20%2F%202D%22%5D%20--%3E%20G%0A%20%20G%20--%3E%20MET%5B%22SEM%20%2F%20OCD%20%E9%85%8D%E6%96%B9%22%5D%0A%20%20MET%20--%3E%20FIT%5B%22%E6%A0%A1%E5%87%86%20%2B%20%E4%BF%9D%E6%8C%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[g(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Gauge 晶圆不是产品良率证明。测太多会变成计量瓶颈，延迟模型版本。不把某代工厂的测试键版图当公开标准。</p><p>后课默认：校准数据有设计好的激励；下一课用残差图判断缺的是光学、胶还是抽样。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Gauge 是实验设计；抽样偏差等于模型盲区。</li><li>计量配方与 SEM 收缩是数据集的一部分。</li><li>保持集要含真实库 clips 与病态节距。</li><li>出处：OPC 校准 gauge 产线通称；计量与模型绑定的公开讨论。</li></ul>',5))])}const T=s(h,[["render",p]]);export{D as __pageData,T as default};
